SELECT 'zone_intent_opener' AS category, COUNT(*) AS must_be_1 FROM playerbot_chat_categories WHERE name = 'zone_intent_opener';


-- ---------------------------------------------------------------------------
-- CATEGORY: aggro (script only -- no triggers, scope 0)
--
-- Driven from Player_Bot.lua event_combat via
--   e.self:PlayerBotChatSayNamed("aggro", 8, e.other:GetCleanName())
-- so {target} resolves to the mob that was just engaged. Zero triggers
-- keeps the classifier out of it; scope 0 keeps the spontaneous scheduler
-- out of it. Guarded so a re-run is a no-op.
-- ---------------------------------------------------------------------------
SELECT 'aggro', 100, 20000, 10, 0, 'SCRIPT ONLY (no triggers): bot engaged something. Player_Bot.lua event_combat'
WHERE NOT EXISTS (SELECT 1 FROM playerbot_chat_categories WHERE name = 'aggro');


